#!/bin/zsh
# 生成兩張寫實比例的原創球員概念圖（不仿任何真實球隊、球員或遊戲）
cd "$(dirname "$0")"
codex exec --skip-git-repo-check "請用內建 image_gen 工具產一張直式 PNG。主題：寫實比例的職業棒球球員角色設定圖（turnaround），同一位原創虛構球員的正面、側面、背面三視圖並排，中性灰背景，攝影棚均勻打光。身高約 188 公分、運動員體型（寬肩、厚實胸背、粗壯大腿），7.5 頭身寫實比例。穿原創設計的白色寬鬆棒球球衣（深海軍藍滾邊、胸前無任何真實球隊字樣，只寫虛構隊名 ISLAND）、及膝的白色棒球褲配深藍長襪、黑色釘鞋、深藍棒球帽、左手戴棕色皮革守備手套。寫實 3D 遊戲角色渲染風格（PBR 材質、布料皺褶、皮膚細節），不要卡通、不要大頭。不要任何真實品牌或聯盟標誌。完成後告訴我產出的圖檔完整路徑。" > fielder.out 2>&1
codex exec --skip-git-repo-check "請用內建 image_gen 工具產一張直式 PNG。主題：寫實比例的職業棒球右打者打擊預備姿勢，原創虛構球員，從捕手斜後方看（打者背面偏側面，看得到本壘板）。7.5 頭身寫實運動員體型。姿勢：雙腳比肩寬、膝蓋微彎朝腳尖、臀部略往後坐、上身微前傾；雙手握棒在後肩上方約耳朵高度、離頭盔約一個頭寬；後手肘抬高接近水平、前手肘朝下，前臂和胸口之間有空間；球棒往背後斜過頭頂。戴深藍打擊頭盔、黑色打擊手套、白色護腕，白色原創球衣（只寫虛構隊名 ISLAND）。寫實 3D 遊戲角色渲染風格（PBR 材質、布料皺褶），中性球場背景虛化。不要卡通、不要大頭、不要任何真實品牌或聯盟標誌。完成後告訴我產出的圖檔完整路徑。" > batter.out 2>&1
echo 完成
